/**
 * Parses an input value into the type described by the JSON Schema, throwing an error if the value cannot be converted into a valid result.
 *
 * @remarks
 * The parser applies default values for missing properties, coerces primitive values to the declared type, and throws an error when the value cannot be converted into a valid result.
 *
 * @param value - The input value to parse.
 * @returns The parsed value conforming to the schema.
 * @throws When the input value cannot be parsed into a valid result according to the schema.
 */
export function parse(value: unknown): Env {
  const result = parseSafe(value);
  if (
    Array.isArray(result) &&
    result.length > 0 &&
    result.every(
      error =>
        "path" in error &&
        typeof error.path === "string" &&
        error.path &&
        "failure" in error &&
        typeof error.failure === "string" &&
        error.failure
    )
  ) {
    throw new Error(
      `The following validation errors occurred while parsing the input value: \n${Object.entries(
        result.reduce(
          (acc, error) => ((acc[error.path] ??= []).push(error.failure), acc),
          {}
        )
      )
        .map(
          ([path, failures]) =>
            `${path.replace(/^\$\./, "") ? `${path.replace(/^\$\./, "")}: \n` : ""}${failures.map(failure => ` - ${failure}`).join("\n")}`
        )
        .join("\n")}`
    );
  }

  return result;
}

